mapper.select:
SELECT * FROM crm_event_nurture_enrollment
WHERE tenant_id = #{tenantId}
  AND sequence_id = #{sequenceId}
  AND audience_key = #{audienceKey}
LIMIT 1

SELECT * FROM crm_event_nurture_enrollment
WHERE tenant_id = #{tenantId}
  AND status = 'active'
  AND next_run_at <= #{now}
ORDER BY next_run_at ASC
LIMIT #{limit}

mapper.update:
UPDATE crm_event_nurture_enrollment
SET current_step_order = #{currentStepOrder},
    next_run_at = #{nextRunAt}
WHERE id = #{id}

UPDATE crm_event_nurture_enrollment
SET status = 'exited',
    exited_at = COALESCE(#{exitedAt}, NOW()),
    exit_reason = #{exitReason}
WHERE id = #{id}
